#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
ios::sync_with_stdio(false);
cin.tie(nullptr);
const int MOD=998244353;
int testCases;
if (!(cin>> testCases)) return 0;
while (testCases--){
    int sz;
    cin>> sz;
    vector <int> arr(sz+1);
    vector<vector<int>> pos(sz+1);
    for(int i=1;i<=sz;i++){
        cin>> arr[i];
        pos[arr[i]].push_back(i);
        }
        vector<long long> dp(sz+2,0),nextDp(sz+2,0);
        dp[0]=1;
        for(int step=1;step<=sz;step++){
            fill(nextDp.begin(),nextDp.end(),0);
            for(int x=0;x<step;x++){
                if(!dp[x]) continue;
                for(int side=0;side<2;side++){
                    if(step==sz&& side ==1)continue;
                    bool valid=true;
                    for(int idx:pos[step]){
                        int h1=(idx+1)/2;
                        int c1=sz-idx+h1;
                        int len2=sz-idx+1;
                        int h2=(len2+1)/2;
                        int c2=idx-1+h2;
                        bool cond1=false, cond2=false;
                        if(step<c1)cond1=(side==0&& x==h1-1);
                        else if (step == c1)cond1=(x<=h1-1);
                         if(step<c2)cond2=(side==1&& x==step-h2);
                        else if (step == c2)cond2=(x>=idx-1);
                        if(!cond1 && !cond2){
                            valid =false;
                            break;
                            
                        }
                    }
                    if(valid){
                        int nx=x+(side==0);
                        nextDp[nx]=(nextDp[nx]+dp[x])%MOD;
                    }
                    }
                }
                swap(dp,nextDp);
            }
            long long totalWays=0;
            for(int x=0;x<=sz;x++){
                totalWays=(totalWays+dp[x])% MOD;
        }
        cout<<totalWays<<'\n';
}
return 0;
    
    
    
    
}
